from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal('0.01')


def _round_cents(value):
    return value.quantize(CENTS, rounding=ROUND_HALF_UP)


def invoice(lines, tax_rate):
    rate = Decimal(tax_rate)
    subtotal = Decimal('0')
    tax = Decimal('0')
    for row in lines:
        rounded_line = _round_cents(Decimal(row['unit_price']) * row['qty'])
        subtotal += rounded_line
        if row['taxable']:
            tax += _round_cents(rounded_line * rate)
    total = subtotal + tax
    return {
        'subtotal': f'{subtotal:.2f}',
        'tax': f'{tax:.2f}',
        'total': f'{total:.2f}',
    }
